WITH valid AS (SELECT id, event_type, duration_sec, ROUND(duration_sec * 1.15, 2) AS duration_sec_adjusted FROM web_events WHERE page IS DISTINCT FROM '/checkout' AND duration_sec < 451), latest AS (SELECT id, event_type, duration_sec, duration_sec_adjusted FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY event_type ORDER BY duration_sec DESC, id) AS row_num FROM valid) t WHERE row_num = 1), ranked AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY event_type ORDER BY duration_sec_adjusted, id) AS rn FROM latest QUALIFY rn = 1), enriched AS (SELECT id, event_type, duration_sec, duration_sec_adjusted, LEAD(duration_sec, 1) OVER (ORDER BY rn, id) AS next_duration_sec, AVG(duration_sec_adjusted) OVER (PARTITION BY event_type ORDER BY duration_sec_adjusted, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS duration_sec_adjusted_avg_6_prior FROM ranked), metrics AS (SELECT id, event_type, duration_sec_adjusted, next_duration_sec, ROW_NUMBER() OVER w_grp AS event_seq, ROW_NUMBER() OVER (PARTITION BY event_type ORDER BY duration_sec DESC, id) AS event_seq_2, SUM(duration_sec_adjusted_avg_6_prior) OVER (PARTITION BY event_type) AS event_type_sum_duration_sec_adjusted_avg_6_prior, LEAD(duration_sec_adjusted_avg_6_prior, 1) OVER w_grp AS next_duration_sec_adjusted_avg_6_prior, RANK() OVER (PARTITION BY event_type ORDER BY duration_sec_adjusted_avg_6_prior DESC) AS duration_sec_adjusted_avg_6_prior_rank FROM enriched WHERE duration_sec_adjusted > 26 WINDOW w_grp AS (PARTITION BY event_type ORDER BY next_duration_sec, id)) SELECT id, duration_sec_adjusted, next_duration_sec, event_seq, event_seq_2, event_type_sum_duration_sec_adjusted_avg_6_prior, next_duration_sec_adjusted_avg_6_prior, duration_sec_adjusted_avg_6_prior_rank FROM metrics;
